mapper.select:
SELECT 
FROM bt_workbench_app a
WHERE a.status_cd = '00A'
  AND a.workbench_app_id = #{workbenchAppId}
  AND a.space_id = #{spaceId}

SELECT a.workbench_app_id, a.app_name, a.auth_type, a.app_scene, a.app_status, a.app_setting_status,
       a.created_time, a.updated_time, a.app_desc,
    (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS creatorName
FROM bt_workbench_app a
WHERE a.status_cd = '00A'
  AND a.space_id = #{query.spaceId}

  AND a.app_name LIKE #{query.appName}


  AND a.app_status = #{query.appStatus}


  AND a.app_scene = #{query.appScene}


  AND a.catalog_item_id = #{query.catalogItemId}

ORDER BY a.updated_time DESC

SELECT app_setting_status
FROM bt_workbench_app
WHERE status_cd = '00A'
  AND workbench_app_id = #{workbenchAppId}
  AND space_id = #{spaceId}

SELECT workbench_app_id, app_name, app_scene, auth_type, space_id
FROM bt_workbench_app
WHERE status_cd = '00A'
  AND workbench_app_id = #{workbenchAppId}
  AND space_id = #{spaceId}

SELECT app_icon
FROM bt_workbench_app
WHERE status_cd = '00A'
  AND workbench_app_id = #{workbenchAppId}
  AND space_id = #{spaceId}

SELECT app_status
FROM bt_workbench_app
WHERE status_cd = '00A'
  AND workbench_app_id = #{workbenchAppId}
  AND space_id = #{spaceId}

SELECT workbench_app_id, app_name, app_status, auth_type, app_scene
FROM bt_workbench_app
WHERE status_cd = '00A'
  AND workbench_app_id = #{workbenchAppId}
  AND space_id = #{spaceId}

SELECT au.workbench_app_id, wa.app_name, wa.app_desc, wa.app_scene, MAX(au.updated_time) as updated_time FROM bt_workbench_app_auth au LEFT JOIN bt_workbench_app wa ON wa.workbench_app_id = au.workbench_app_id AND wa.status_cd = '00A' LEFT JOIN bt_organization o ON o.org_id = au.org_id AND o.status_cd = '00A' WHERE au.status_cd = '00A' AND au.space_id = #{query.spaceId} AND wa.app_status = 'A' AND (au.user_id IN (#{query.userId}, -1)
OR au.org_id IN (#{orgId})
)
AND wa.catalog_item_id = #{query.catalogItemId}
AND wa.app_name LIKE #{query.appName}
GROUP BY au.workbench_app_id, wa.app_name, wa.app_desc, wa.app_scene ORDER BY updated_time DESC

SELECT DISTINCT c.bot_id, c.tenant_id, c.bot_name, c.bot_use, c.updated_time FROM bt_workbench_app a LEFT JOIN bt_workbench_app_rel b ON a.workbench_app_id = b.workbench_app_id LEFT JOIN bt_bot c ON b.rel_app_id = c.bot_id AND b.tenant_id = c.tenant_id AND rel_app_type = 'aiBot' LEFT JOIN bt_workbench_app_auth d ON a.workbench_app_id = d.workbench_app_id LEFT JOIN bt_organization o ON o.org_id = d.org_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND c.status_cd = '00A' AND d.status_cd = '00A' AND a.app_status = 'A' AND a.space_id = #{query.spaceId} AND (d.user_id IN (#{query.userId}, -1)
OR d.org_id IN (#{orgId})
)
AND c.bot_name LIKE #{query.searchContent}
ORDER BY c.updated_time DESC

SELECT DISTINCT c.web_app_id, c.space_id, c.app_name, c.open_type, c.access_url, c.auth_type, c.updated_time FROM bt_workbench_app a LEFT JOIN bt_workbench_app_rel b ON a.workbench_app_id = b.workbench_app_id LEFT JOIN bt_web_app c ON b.rel_app_id = c.web_app_id AND b.space_id = c.space_id AND rel_app_type = 'webApp' LEFT JOIN bt_workbench_app_auth d ON a.workbench_app_id = d.workbench_app_id LEFT JOIN bt_organization o ON o.org_id = d.org_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND c.status_cd = '00A' AND d.status_cd = '00A' AND a.app_status = 'A' AND a.space_id = #{query.spaceId} AND (d.user_id IN (#{query.userId}, -1)
OR d.org_id IN (#{orgId})
)
AND c.app_name LIKE #{query.searchContent}
ORDER BY c.updated_time DESC
